// UniPlan - Process Operation (sub-workflow). All reads arrive pre-filtered by user_id and are re-checked here.
const TIMEZONE = 'Europe/Paris';   // any IANA name, e.g. 'America/New_York'
const MAX_CLASSES_PER_USER = 100;
const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];

const req = $('Sub-workflow Trigger').first().json;
const operation = String(req.operation || '');
const userId = String(req.userId || '');
const chatId = String(req.chatId || '');
if (!userId || !chatId) throw new Error('Missing userId or chatId');

const out = (o) => [{ json: Object.assign({ operation, userId, chatId, writeAction: 'none', status: 'ok' }, o) }];
const dayIndex = (d) => DAYS.findIndex(x => x.toLowerCase() === String(d || '').trim().toLowerCase());
const toMin = (t) => {
  if (t === null || t === undefined || t === '') return NaN;
  if (typeof t === 'number') return t < 1 ? Math.round(t * 1440) : NaN;   // Sheets time serial fallback
  const m = String(t).trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : NaN;
};
const fmt = (min) => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');
const human = (mins) => {
  const d = Math.floor(mins / 1440), h = Math.floor((mins % 1440) / 60), m = mins % 60;
  const p = [];
  if (d) p.push(d + 'd'); if (h) p.push(h + 'h'); if (m || !p.length) p.push(m + 'm');
  return p.join(' ');
};

const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const labelOf = (code, desc) => [code, desc].filter(Boolean).join(' – ') || '(untitled)';
const extrasOf = (room, teacher, credits) => '(' + (room ? 'Room ' + room : 'Room TBD') + ')' + (teacher ? ' · ' + teacher : '') + (credits ? ' · ' + credits + ' cr' : '');
const line = (r) => '• ' + fmt(r.start) + '–' + fmt(r.end) + ' ' + labelOf(r.code, r.desc) + ' ' + extrasOf(r.room, r.teacher, r.credits) + ' [' + r.classId + ']';

// Only this user's rows (defence in depth on top of the Sheets lookup filter)
const owned = $input.all().map(i => i.json)
  .filter(r => r && r.class_id && String(r.user_id) === userId);
const rows = owned.map(r => ({
  classId: str(r.class_id), code: str(r.class_code), desc: str(r.class_description),
  day: dayIndex(r.day), start: toMin(r.start_time), end: toMin(r.end_time),
  room: str(r.room), teacher: str(r.teacher), credits: str(r.credits)
})).filter(r => r.day >= 0 && !isNaN(r.start) && !isNaN(r.end))
  .sort((a, b) => a.day - b.day || a.start - b.start || a.end - b.end);

if (operation === 'schedule') {
  if (!rows.length) {
    return out({ status: 'empty', logAction: 'schedule', logStatus: 'success', logDetails: 'classes=0',
      replyText: '📭 Your timetable is empty.\n\nAdd a class with:\n/add ClassName | Day | StartTime | EndTime | Room\nExample: /add Databases | Monday | 10:00 | 12:00 | B204' });
  }
  let text = '📅 Your timetable (' + rows.length + (rows.length === 1 ? ' class' : ' classes') + ')\n';
  DAYS.forEach((d, i) => {
    const list = rows.filter(r => r.day === i);
    if (!list.length) return;
    text += '\n' + d + '\n';
    list.forEach(r => { text += line(r) + '\n'; });
  });
  text += '\nRemove a class with /drop ClassID';
  if (text.length > 3900) text = text.slice(0, 3850) + '\n… (truncated)';
  return out({ replyText: text, logAction: 'schedule', logStatus: 'success', logDetails: 'classes=' + rows.length });
}

const dayList = (idx, label) => {
  const list = rows.filter(r => r.day === idx);
  if (!list.length) {
    return out({ status: 'empty', logAction: operation, logStatus: 'success', logDetails: 'classes=0',
      replyText: '🎉 No classes ' + (label ? label + ' (' + DAYS[idx] + ')' : 'on ' + DAYS[idx]) + '.' });
  }
  let text = '📅 ' + (label ? label.charAt(0).toUpperCase() + label.slice(1) + ' – ' : '') + DAYS[idx] + ' (' + list.length + (list.length === 1 ? ' class' : ' classes') + ')\n\n';
  list.forEach(r => { text += line(r) + '\n'; });
  return out({ replyText: text.trim(), logAction: operation, logStatus: 'success', logDetails: 'classes=' + list.length });
};
if (operation === 'today' || operation === 'tomorrow') {
  const now = $now.setZone(TIMEZONE);
  if (!now.isValid) throw new Error('Invalid TIMEZONE constant in Process Operation node: ' + TIMEZONE);
  const idx = (now.weekday - 1 + (operation === 'tomorrow' ? 1 : 0)) % 7;
  return dayList(idx, operation);
}
if (operation === 'day') {
  const idx = dayIndex(req.day);
  if (idx < 0) return out({ status: 'rejected', logAction: 'day', logStatus: 'rejected', logDetails: 'invalid day', replyText: '⚠️ Invalid day. Use Monday to Sunday.' });
  return dayList(idx, '');
}

if (operation === 'next') {
  if (!rows.length) {
    return out({ status: 'empty', logAction: 'next', logStatus: 'success', logDetails: 'classes=0',
      replyText: '📭 You have no classes yet. Add one with /add (see /help).' });
  }
  const now = $now.setZone(TIMEZONE);
  if (!now.isValid) throw new Error('Invalid TIMEZONE constant in Process Operation node: ' + TIMEZONE);
  const nowDay = now.weekday - 1;                 // Monday = 0
  const nowMin = now.hour * 60 + now.minute;
  const ongoing = rows.filter(r => r.day === nowDay && r.start <= nowMin && nowMin < r.end);
  let best = null;
  rows.forEach(r => {
    let total = ((r.day - nowDay + 7) % 7) * 1440 + r.start - nowMin;
    let wrapped = false;
    if (total < 0) { total += 7 * 1440; wrapped = true; }   // already started: next occurrence is next week
    if (!best || total < best.total) best = { r, total, wrapped };
  });
  const calDays = ((best.r.day - nowDay + 7) % 7) + (best.wrapped ? 7 : 0);
  const when = calDays === 0 ? 'today' : calDays === 1 ? 'tomorrow' : calDays === 7 ? 'next ' + DAYS[best.r.day] : 'on ' + DAYS[best.r.day];
  let text = '';
  if (ongoing.length) text += '▶️ In progress: ' + ongoing.map(r => labelOf(r.code, r.desc) + ' (until ' + fmt(r.end) + ')').join(', ') + '\n\n';
  text += '⏭ Next class: ' + labelOf(best.r.code, best.r.desc) + '\n' + DAYS[best.r.day] + ' ' + fmt(best.r.start) + '–' + fmt(best.r.end) +
    ' ' + extrasOf(best.r.room, best.r.teacher, best.r.credits) + '\nStarts ' + when + (best.total === 0 ? ' (now!)' : ' (in ' + human(best.total) + ')') +
    '\n\nTimezone: ' + TIMEZONE;
  return out({ replyText: text, logAction: 'next', logStatus: 'success', logDetails: 'class_id=' + best.r.classId });
}

if (operation === 'add') {
  const code = str(req.classCode), desc = str(req.classDescription), room = str(req.room), teacher = str(req.teacher), credits = str(req.credits);
  const day = dayIndex(req.day), start = toMin(req.startTime), end = toMin(req.endTime);
  if ((!code && !desc) || day < 0 || isNaN(start) || isNaN(end) || end <= start) {
    return out({ status: 'rejected', logAction: 'add', logStatus: 'rejected', logDetails: 'sub-workflow validation failed',
      replyText: '⚠️ Invalid class details. A class needs a code or description, a day, and a valid start/end time. Send /help for the syntax.' });
  }
  if (rows.length >= MAX_CLASSES_PER_USER) {
    return out({ status: 'rejected', logAction: 'add', logStatus: 'rejected', logDetails: 'class limit reached',
      replyText: '⚠️ You have reached the limit of ' + MAX_CLASSES_PER_USER + ' classes. Remove one with /drop first.' });
  }
  const conflicts = rows.filter(r => r.day === day && start < r.end && end > r.start);   // touching times are allowed
  if (conflicts.length) {
    return out({ status: 'conflict', logAction: 'add', logStatus: 'conflict',
      logDetails: 'overlaps=' + conflicts.map(c => c.classId).join(','),
      replyText: '⚠️ Scheduling conflict – nothing was saved.\n' + labelOf(code, desc) + ' (' + DAYS[day] + ' ' + fmt(start) + '–' + fmt(end) +
        ') overlaps with:\n' + conflicts.map(c => '• ' + labelOf(c.code, c.desc) + ' ' + fmt(c.start) + '–' + fmt(c.end) + ' [' + c.classId + ']').join('\n') +
        '\n\nPick another time or /drop the existing class first.' });
  }
  const taken = new Set(owned.map(r => String(r.class_id).toUpperCase()));
  let classId;
  do {
    classId = 'C' + Math.floor(Date.now() / 1000).toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase();
  } while (taken.has(classId));
  const missing = [!room && 'room', !teacher && 'teacher', !credits && 'credits'].filter(Boolean);
  return out({
    writeAction: 'append',
    row: { class_id: classId, user_id: userId, class_code: code, class_description: desc, day: DAYS[day], start_time: fmt(start), end_time: fmt(end), room, teacher, credits },
    logAction: 'add', logStatus: 'success', logDetails: 'class_id=' + classId,
    replyText: '✅ Class added\n' + labelOf(code, desc) + '\n' + DAYS[day] + ' ' + fmt(start) + '–' + fmt(end) + ' ' + extrasOf(room, teacher, credits) + '\nID: ' + classId +
      (missing.length ? '\n\nStill unknown: ' + missing.join(', ') + '. Fill in later with /edit ' + classId + ' | ' + missing[0] + ' | value' : '')
  });
}

if (operation === 'edit') {
  const target = String(req.classId || '').trim().toUpperCase();
  const field = String(req.field || '');
  const value = str(req.value);
  const OPTIONAL = ['class_code', 'class_description', 'room', 'teacher', 'credits'];
  const rej = (msg, why) => out({ status: 'rejected', logAction: 'edit', logStatus: 'rejected', logDetails: why, replyText: msg });
  if (![...OPTIONAL, 'day', 'start_time', 'end_time'].includes(field)) return rej('⚠️ Invalid edit request. Send /help for the syntax.', 'invalid request');
  const cur = rows.find(r => r.classId.toUpperCase() === target);   // owned rows only
  if (!cur) {
    return out({ status: 'not_found', logAction: 'edit', logStatus: 'not_found', logDetails: 'class_id=' + target.slice(0, 32),
      replyText: 'No class with ID ' + target.slice(0, 32) + ' was found in your timetable.\nUse /schedule to see your class IDs.' });
  }
  const n = { code: cur.code, desc: cur.desc, day: cur.day, start: cur.start, end: cur.end, room: cur.room, teacher: cur.teacher, credits: cur.credits };
  if (field === 'class_code') n.code = value;
  else if (field === 'class_description') n.desc = value;
  else if (field === 'room') n.room = value;
  else if (field === 'teacher') n.teacher = value;
  else if (field === 'credits') n.credits = value;
  else if (field === 'day') { const d = dayIndex(value); if (d < 0) return rej('⚠️ Invalid day.', 'invalid day'); n.day = d; }
  else { const t = toMin(value); if (isNaN(t)) return rej('⚠️ Invalid time. Use HH:MM.', 'invalid time'); if (field === 'start_time') n.start = t; else n.end = t; }
  if (!n.code && !n.desc) return rej('⚠️ A class needs at least a code or a description. Nothing was changed.', 'no class identifier');
  if (n.end <= n.start) return rej('⚠️ End time must be later than start time (' + fmt(n.start) + ' → ' + fmt(n.end) + '). Nothing was changed.', 'end not after start');
  const conflicts = rows.filter(r => r.classId !== cur.classId && r.day === n.day && n.start < r.end && n.end > r.start);
  if (conflicts.length) {
    return out({ status: 'conflict', logAction: 'edit', logStatus: 'conflict', logDetails: 'overlaps=' + conflicts.map(c => c.classId).join(','),
      replyText: '⚠️ Scheduling conflict – nothing was changed.\n' + labelOf(n.code, n.desc) + ' (' + DAYS[n.day] + ' ' + fmt(n.start) + '–' + fmt(n.end) +
        ') would overlap with:\n' + conflicts.map(c => '• ' + labelOf(c.code, c.desc) + ' ' + fmt(c.start) + '–' + fmt(c.end) + ' [' + c.classId + ']').join('\n') });
  }
  return out({
    writeAction: 'edit',
    row: { class_id: cur.classId, user_id: userId, class_code: n.code, class_description: n.desc, day: DAYS[n.day], start_time: fmt(n.start), end_time: fmt(n.end), room: n.room, teacher: n.teacher, credits: n.credits },
    logAction: 'edit', logStatus: 'success', logDetails: 'class_id=' + cur.classId + '; field=' + field,
    replyText: '✏️ Class updated\n' + labelOf(n.code, n.desc) + '\n' + DAYS[n.day] + ' ' + fmt(n.start) + '–' + fmt(n.end) + ' ' + extrasOf(n.room, n.teacher, n.credits) + '\nID: ' + cur.classId
  });
}

if (operation === 'import') {
  const meetings = Array.isArray(req.meetings) ? req.meetings : [];
  const notes = (Array.isArray(req.skipped) ? req.skipped : []).map(x => String(x).slice(0, 160));
  const accepted = [];
  const taken = new Set(owned.map(r => String(r.class_id).toUpperCase()));
  const newId = () => {
    let id;
    do { id = 'C' + Math.floor(Date.now() / 1000).toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase(); } while (taken.has(id));
    taken.add(id);
    return id;
  };
  meetings.slice(0, 20).forEach((m) => {
    const code = str(m.classCode), desc = str(m.classDescription), room = str(m.room), teacher = str(m.teacher), credits = str(m.credits);
    const day = dayIndex(m.day), start = toMin(m.startTime), end = toMin(m.endTime);
    const lbl = labelOf(code, desc);
    if ((!code && !desc) || day < 0 || isNaN(start) || isNaN(end) || end <= start) { notes.push(lbl + ': invalid details, skipped.'); return; }
    if (rows.length + accepted.length >= MAX_CLASSES_PER_USER) { notes.push(lbl + ' ' + DAYS[day] + ': class limit (' + MAX_CLASSES_PER_USER + ') reached, skipped.'); return; }
    const clash = rows.concat(accepted).filter(r => r.day === day && start < r.end && end > r.start);
    if (clash.length) {
      notes.push(lbl + ' ' + DAYS[day] + ' ' + fmt(start) + '–' + fmt(end) + ' overlaps ' + clash.map(c => labelOf(c.code, c.desc) + ' ' + fmt(c.start) + '–' + fmt(c.end)).join(', ') + ' – skipped.');
      return;
    }
    accepted.push({ classId: newId(), code, desc, day, start, end, room, teacher, credits });
  });
  if (!accepted.length) {
    return out({ status: 'rejected', logAction: 'import', logStatus: 'rejected', logDetails: 'added=0; skipped=' + notes.length + '; meetings_read=' + meetings.length,
      replyText: '⚠️ Nothing was imported.' + (meetings.length ? '' : '\nI could not find any readable classes in that image.') +
        (notes.length ? '\n\n' + notes.map(n => '• ' + n).join('\n') : '') + '\n\nTry a clearer, tighter screenshot, or add classes manually with /add.' });
  }
  const unknown = [accepted.some(a => !a.room) && 'room', accepted.some(a => !a.teacher) && 'teacher', accepted.some(a => !a.credits) && 'credits'].filter(Boolean);
  let text = '📥 Imported ' + accepted.length + (accepted.length === 1 ? ' class meeting' : ' class meetings') + ':\n\n' + accepted.map(line).join('\n');
  if (notes.length) text += '\n\n⚠️ Not imported:\n' + notes.map(n => '• ' + n).join('\n');
  if (unknown.length) text += '\n\nNot found in the image: ' + unknown.join(', ') + ' (add later with /edit).';
  text += '\n\nPlease double-check the details – fix with /edit or remove with /drop.';
  if (text.length > 3900) text = text.slice(0, 3850) + '\n… (truncated)';
  return out({
    writeAction: 'import',
    rows: accepted.map(a => ({ class_id: a.classId, user_id: userId, class_code: a.code, class_description: a.desc, day: DAYS[a.day],
      start_time: fmt(a.start), end_time: fmt(a.end), room: a.room, teacher: a.teacher, credits: a.credits })),
    logAction: 'import', logStatus: 'success',
    logDetails: 'added=' + accepted.length + '; skipped=' + notes.length + '; class_ids=' + accepted.map(a => a.classId).join(','),
    replyText: text
  });
}

if (operation === 'drop') {
  const target = String(req.classId || '').trim().toUpperCase();
  const match = owned.find(r => String(r.class_id).trim().toUpperCase() === target);   // owned rows only
  if (!match) {
    return out({ status: 'not_found', logAction: 'drop', logStatus: 'not_found', logDetails: 'class_id=' + target.slice(0, 32),
      replyText: 'No class with ID ' + target.slice(0, 32) + ' was found in your timetable.\nUse /schedule to see your class IDs.' });
  }
  const cid = String(match.class_id).trim();
  return out({
    writeAction: 'drop', classId: cid,
    logAction: 'drop', logStatus: 'success', logDetails: 'class_id=' + cid,
    replyText: '🗑 Removed: ' + labelOf(str(match.class_code), str(match.class_description)) + ' (' + str(match.day) + ' ' + str(match.start_time) + '–' + str(match.end_time) + ')'
  });
}

throw new Error('Unsupported operation: ' + operation);
